// US-086: verifica que el aviso venga de AlToque (HMAC-SHA256 con el secreto
// compartido), que no sea viejo (más de 5 minutos) y que no sea repetido.
const crypto = require('crypto');
const secreto = $input.first().json.secreto;
if (typeof secreto !== 'string' || secreto.length < 32) {
  throw new Error('Configura el secreto compartido (mínimo 32 caracteres) antes de publicar');
}
const entrada = $('Webhook').first().json;
const cabeceras = entrada.headers || {};
const aviso = entrada.body;
const tiempo = Number(cabeceras['x-altoque-timestamp']);
const firma = String(cabeceras['x-altoque-firma'] || '');
const ahora = Math.floor(Date.now() / 1000);

let valido = false;
let motivo = '';
if (!Number.isInteger(tiempo) || Math.abs(ahora - tiempo) > 300) {
  motivo = 'hora ausente o fuera de los 5 minutos';
} else if (!/^sha256=[0-9a-f]{64}$/.test(firma)) {
  motivo = 'firma ausente o mal formada';
} else if (!aviso || typeof aviso !== 'object' || aviso.evento !== 'pago_confirmado' || typeof aviso.id !== 'string') {
  motivo = 'contenido no reconocido';
} else {
  // AlToque firma el JSON exacto que envía; leerlo y reescribirlo da el mismo texto.
  const esperada = crypto.createHmac('sha256', secreto)
    .update(`${tiempo}.${JSON.stringify(aviso)}`, 'utf8').digest();
  const recibida = Buffer.from(firma.slice(7), 'hex');
  valido = recibida.length === esperada.length && crypto.timingSafeEqual(recibida, esperada);
  if (!valido) motivo = 'firma inválida';
}

// Un mismo pago puede avisarse dos veces (reintento de caja): se recuerda el id.
let duplicado = false;
if (valido) {
  const memoria = $getWorkflowStaticData('global');
  memoria.pagosAvisados = memoria.pagosAvisados || [];
  duplicado = memoria.pagosAvisados.includes(aviso.id);
  if (!duplicado) memoria.pagosAvisados = [...memoria.pagosAvisados, aviso.id].slice(-500);
}

// Nunca se devuelve el secreto ni la firma.
return [{ json: { valido, motivo, duplicado, aviso: valido ? aviso : null } }];
